import json

def solve(data):
    events = data.get("events", []) if isinstance(data, dict) else []
    groups = {}
    order = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        eid = ev.get("id")
        if not isinstance(eid, str):
            continue
        body = json.dumps(ev, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        if eid not in groups:
            groups[eid] = {}
            order.append(eid)
        groups[eid][body] = ev
    unamb = {}
    for eid, bodies in groups.items():
        if len(bodies) == 1:
            unamb[eid] = next(iter(bodies.values()))
    # deps per unambiguous event
    deps = {}
    for eid, ev in unamb.items():
        d = ev.get("deps", [])
        if not isinstance(d, list):
            d = []
        deps[eid] = [x for x in d if isinstance(x, str)]
    # least fixpoint: eligible iff all deps eligible
    eligible = set()
    changed = True
    while changed:
        changed = False
        for eid in unamb:
            if eid in eligible:
                continue
            if all(x in eligible for x in deps[eid]):
                eligible.add(eid)
                changed = True
    # ancestors (strict transitive) for eligible events
    anc_cache = {}
    def ancestors(eid):
        if eid in anc_cache:
            return anc_cache[eid]
        seen = set()
        stack = list(deps[eid])
        while stack:
            x = stack.pop()
            if x in seen:
                continue
            seen.add(x)
            stack.extend(deps.get(x, []))
        anc_cache[eid] = seen
        return seen
    removed = set()
    for eid in eligible:
        ev = unamb[eid]
        if ev.get("kind") != "remove":
            continue
        targets = ev.get("targets", [])
        if not isinstance(targets, list):
            targets = []
        anc = ancestors(eid)
        for t in targets:
            if not isinstance(t, str) or t not in eligible or t == eid:
                continue
            tev = unamb[t]
            if tev.get("kind") != "add":
                continue
            if tev.get("key") != ev.get("key"):
                continue
            if t in anc:
                removed.add(t)
    live = [e for e in eligible if unamb[e].get("kind") == "add" and e not in removed]
    return {"eligible": sorted(eligible), "live": sorted(live)}

