import json


def solve(data):
    groups = {}
    for event in data['events']:
        body = json.dumps(event, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
        groups.setdefault(event['id'], {})[body] = event
    events = {eid: next(iter(bodies.values()))
              for eid, bodies in groups.items() if len(bodies) == 1}

    # Build eligibility and strict ancestor closures in dependency order.
    ancestors = {}
    while True:
        changed = False
        for eid, event in events.items():
            if eid in ancestors:
                continue
            if all(dep in ancestors for dep in event['deps']):
                closure = set(event['deps'])
                for dep in event['deps']:
                    closure.update(ancestors[dep])
                ancestors[eid] = closure
                changed = True
        if not changed:
            break

    live = {eid for eid in ancestors if events[eid]['kind'] == 'add'}
    for eid in ancestors:
        event = events[eid]
        if event['kind'] == 'remove':
            for target in event['targets']:
                if (target in live and target in ancestors[eid]
                        and events[target]['key'] == event['key']):
                    live.remove(target)
    return {'eligible': sorted(ancestors), 'live': sorted(live)}

