def solve(data):
    jobs = data["jobs"]
    setup = data["setup"]
    blackouts = sorted([tuple(b) for b in data.get("blackouts", [])])
    n = len(jobs)
    idx = {j["id"]: i for i, j in enumerate(jobs)}

    def place(start, dur):
        # move start forward past overlapping blackouts
        changed = True
        while changed:
            changed = False
            for a, b in blackouts:
                if a < start + dur and start < b:
                    start = b
                    changed = True
        return start

    best = [None]  # (-(value), completion, ids)

    def consider(val, t, seq):
        key = (-val, t, list(seq))
        if best[0] is None or key < best[0]:
            best[0] = key

    def dfs(selected, t, f, val, seq):
        consider(val, t, seq)
        for i in range(n):
            if selected & (1 << i):
                continue
            j = jobs[i]
            ok = True
            for d in j["deps"]:
                if d not in idx or not (selected & (1 << idx[d])):
                    ok = False
                    break
            if not ok:
                continue
            s = max(j["release"], t + setup[f][j["family"]])
            s = place(s, j["duration"])
            c = s + j["duration"]
            if c > j["deadline"]:
                continue
            seq.append(j["id"])
            dfs(selected | (1 << i), c, j["family"], val + j["value"], seq)
            seq.pop()

    dfs(0, 0, 0, 0, [])
    return best[0][2]

