import json

def solve(data):
    groups = {}
    for event in data['events']:
        body = json.dumps(event, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
        groups.setdefault(event['id'], {})[body] = event

    unique = {
        eid: next(iter(bodies.values()))
        for eid, bodies in groups.items()
        if len(bodies) == 1
    }

    # An ID is admitted only after all its dependencies have been admitted.
    ancestors = {}
    while True:
        changed = False
        for eid, event in unique.items():
            if eid in ancestors:
                continue
            if all(dep in ancestors for dep in event['deps']):
                closure = set(event['deps'])
                for dep in event['deps']:
                    closure.update(ancestors[dep])
                ancestors[eid] = closure
                changed = True
        if not changed:
            break

    live = {eid for eid in ancestors if unique[eid]['kind'] == 'add'}
    for eid, closure in ancestors.items():
        event = unique[eid]
        if event['kind'] == 'remove':
            for target in event['targets']:
                if (target in live and target in closure
                        and unique[target]['key'] == event['key']):
                    live.remove(target)

    return {'eligible': sorted(ancestors), 'live': sorted(live)}

